#!/usr/bin/env python3
"""Generate fully-rendered, search-friendly HTML from content/*.json. No dependencies."""
from pathlib import Path
from html import escape
from email.utils import format_datetime
import json, re, math, datetime
from xml.sax.saxutils import escape as xml_escape
R=Path(__file__).resolve().parent
A=json.loads((R/'content/articles.json').read_text(encoding='utf-8'))
CAT=json.loads((R/'content/categories.json').read_text(encoding='utf-8'))
SRC=json.loads((R/'content/sources.json').read_text(encoding='utf-8'))
BASE='https://paksights.com/'
LATEST=max(a['reviewed'] for a in A)
def fmt_date(s):
    dt=datetime.date.fromisoformat(s)
    return f'{dt.day} {dt.strftime("%b %Y")}'
def rss_date(s):
    return format_datetime(datetime.datetime.fromisoformat(s).replace(tzinfo=datetime.timezone.utc))
def E(x):return escape(str(x),quote=True)
def ic(n,sz=21):
    paths={
    'arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>','arrow-up-right':'<path d="M7 17 17 7M7 7h10v10"/>',
    'search':'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
    'id-card':'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="8.5" cy="11" r="2"/><path d="M5.5 16c0-2 6-2 6 0M14 10h4m-4 4h4"/>',
    'wallet':'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M3 9V5a2 2 0 0 1 2-2h13M17 13h4m-4 0h-1"/>',
    'house':'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1z"/>',
    'users':'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2c0-3 2.5-5 6-5s6 2 6 5v2M16 5a3 3 0 0 1 0 6m2 3c2 .5 3 2 3 4v2"/>',
    'life-buoy':'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="m5.6 5.6 3.5 3.5m5.8 5.8 3.5 3.5m0-12.8-3.5 3.5m-5.8 5.8-3.5 3.5"/>',
    'file':'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8m-8 4h8"/>',
    'check':'<path d="m5 12 5 5L20 7"/>','check-circle':'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',
    'globe':'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/>',
    'clock':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
    'shield':'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/>',
    'external':'<path d="M13 5h6v6M19 5l-9 9M19 14v5H5V5h5"/>',
    'bookmark':'<path d="M5 4a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v17l-7-4-7 4z"/>',
    'print':'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v8H6zM18 12h.01"/>',
    'menu':'<path d="M4 6h16M4 12h16M4 18h16"/>','x':'<path d="M5 5l14 14M19 5 5 19"/>',
    'filter':'<path d="M4 7h16M7 12h10m-7 5h4"/>',
    'link':'<path d="M10 13a5 5 0 0 0 7 .2l2-2a5 5 0 0 0-7-7l-2 2"/><path d="M14 11a5 5 0 0 0-7-.2l-2 2a5 5 0 0 0 7 7l2-2"/>',
    'alert':'<path d="m12 3 10 18H2zM12 9v5m0 3h.01"/>','heart':'<path d="M20 9c0 5-8 11-8 11S4 14 4 9a4.5 4.5 0 0 1 8-2 4.5 4.5 0 0 1 8 2z"/>',
    'calculator':'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8v4H8zm0 8h1m4 0h1m-6 4h1m4 0h1"/>',
    'compass':'<circle cx="12" cy="12" r="9"/><path d="m15.5 8.5-2 5-5 2 2-5z"/>',
    'mail':'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 7 9-7"/>',
    'copy':'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h2"/>',
    'chevron':'<path d="m9 18 6-6-6-6"/>',
    'sparkle':'<path d="m12 2 2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2z"/>',
    }
    return f'<svg aria-hidden="true" width="{sz}" height="{sz}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{paths.get(n,paths["file"])}</svg>'
def href_guide(a,prefix=''):return prefix+'guides/'+a['slug']+'.html'
def href_cat(c,prefix=''):return prefix+'topics/'+c+'.html'
def catpill(c,prefix=''):return f'<a class="topic-mini" href="{href_cat(c,prefix)}">{E(CAT[c]["name"])}</a>'
def rt(a):
    wordcount=len(re.findall(r'\w+',json.dumps(a,ensure_ascii=False)))
    return max(3,math.ceil(wordcount/210))
def card(a,prefix='',featured=False):
    return f'''<article class="guide-card {'guide-card--featured' if featured else ''}">
    <div class="guide-card-top"><span class="pill pill--{CAT[a['category']]['tone']}">{ic(CAT[a['category']]['icon'],15)} {E(CAT[a['category']]['name'])}</span><span class="muted small">{rt(a)} min read</span></div>
    <h3><a href="{href_guide(a,prefix)}">{E(a['title'])}</a></h3><p>{E(a['deck'])}</p>
    <a class="readlink" href="{href_guide(a,prefix)}">Read guide {ic('arrow',17)}</a></article>'''
def header(prefix='',active=''):
    nav=[('Guides','guides/index.html','guides'),('Topics','topics/index.html','topics'),('Free tools','tools/index.html','tools'),('Official sources','sources.html','sources')]
    links=''.join(f'<a class="{"active" if active==k else ""}" href="{prefix+u}">{name}</a>' for name,u,k in nav)
    return f'''<a class="skip-link" href="#main">Skip to content</a><div class="utility-bar"><div class="container utility-inner"><span>{ic('globe',14)} Independent guides for Pakistanis worldwide</span><span class="utility-right">Last source review: {fmt_date(LATEST)}</span></div></div>
    <header class="site-header"><div class="container nav-inner"><a class="brand" href="{prefix}index.html" aria-label="PakSights home"><span class="brand-logo">{ic('compass',26)}</span><span class="brand-text"><span class="brand-name">Pak<strong>Sights</strong></span><small>OVERSEAS GUIDE</small></span></a>
    <nav class="desktop-nav" aria-label="Main navigation">{links}</nav><div class="nav-actions"><button class="icon-button search-launch" aria-label="Search guides" title="Search guides">{ic('search',21)}</button><a class="btn btn-primary btn-sm nav-guide" href="{prefix}guides/index.html">Explore guides {ic('arrow-up-right',16)}</a><button class="icon-button mobile-toggle" aria-expanded="false" aria-controls="mobile-nav" aria-label="Open navigation">{ic('menu',23)}</button></div></div>
    <nav id="mobile-nav" class="mobile-nav container" aria-label="Mobile navigation">{links}</nav></header>'''
def footer(prefix=''):
    topics=''.join(f'<a href="{href_cat(c,prefix)}">{E(v["name"])}</a>' for c,v in CAT.items())
    return f'''<footer class="footer"><div class="container footer-grid"><div class="footer-brand"><a class="brand brand--footer" href="{prefix}index.html"><span class="brand-logo">{ic('compass',24)}</span><span class="brand-text"><span class="brand-name">Pak<strong>Sights</strong></span><small>OVERSEAS GUIDE</small></span></a><p>Practical, carefully sourced guidance for Pakistanis building lives across borders.</p><div class="independent-note">{ic('shield',17)} Independent publication. Not affiliated with any government agency.</div></div>
    <div class="footer-col"><h4>Explore</h4><a href="{prefix}guides/index.html">All guides</a>{topics}</div><div class="footer-col"><h4>Resources</h4><a href="{prefix}tools/index.html">Free tools</a><a href="{prefix}sources.html">Source directory</a><a href="{prefix}editorial-policy.html">Editorial standards</a><a href="{prefix}about.html">About PakSights</a></div><div class="footer-col"><h4>Information</h4><a href="{prefix}contact.html">Contact & corrections</a><a href="{prefix}privacy.html">Privacy</a><a href="{prefix}disclaimer.html">Disclaimer</a><a href="{prefix}terms.html">Terms of use</a></div></div><div class="container footer-bottom"><span>© 2026 PakSights. Made for the global Pakistani community.</span><span>Check official sources before acting on legal, tax or document matters.</span></div></footer>
    <dialog id="search-dialog" class="search-dialog"><div class="search-dialog-head"><div><strong>Find a clear answer</strong><p>Search topics, documents and practical guides</p></div><button class="icon-button dialog-close" aria-label="Close search">{ic('x',22)}</button></div><label class="search-field"><span>{ic('search',22)}</span><input id="global-search" type="search" placeholder="Try NICOP, property, bank complaint…" autocomplete="off" aria-label="Search all guides"/><kbd>ESC</kbd></label><div class="search-results" id="global-search-results"></div><div class="search-dialog-foot">{len(A)} detailed guides · official links · free to read</div></dialog>
    <script src="{prefix}assets/js/site-config.js" defer></script><script src="{prefix}assets/js/search-index.js" defer></script><script src="{prefix}assets/js/main.js" defer></script>'''
def document(title,desc,body,path='',prefix='',active='',schema=None,extra_js='',noindex=False):
    url=BASE+('' if path=='index.html' else path)
    structured=f'<script type="application/ld+json">{json.dumps(schema,ensure_ascii=False).replace("</","<\\/")}</script>' if schema else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ffffff">
    <title>{E(title)} | PakSights</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{E(url)}">
    <meta property="og:type" content="{'article' if path.startswith('guides/') else 'website'}"><meta property="og:site_name" content="PakSights"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{E(url)}"><meta property="og:image" content="https://paksights.com/assets/img/social-card.png"><meta name="twitter:card" content="summary_large_image">
    {'<meta name="robots" content="noindex,follow">' if noindex else ''}<link rel="icon" href="{prefix}assets/img/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/css/style.css">{structured}</head><body>{header(prefix,active)}<main id="main">{body}</main>{footer(prefix)}{f'<script src="{prefix}{extra_js}" defer></script>' if extra_js else ''}</body></html>'''
def write(path,html):
    f=R/path; f.parent.mkdir(parents=True,exist_ok=True); f.write_text(html,encoding='utf-8')
    return path

def breadcrumb(items,prefix=''):
    res=['<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="'+prefix+'index.html">Home</a>']
    for i,(name,url) in enumerate(items):
        res.append(ic('chevron',14)); res.append(f'<span aria-current="page">{E(name)}</span>' if i==len(items)-1 else f'<a href="{prefix+url}">{E(name)}</a>')
    return ''.join(res)+'</nav>'
def ld_breadcrumb(trail):
    return {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':name,'item':BASE+url} for i,(name,url) in enumerate(trail)]}

def home():
    tiles=''.join(f'''<a class="topic-card topic-card--{v['tone']}" href="{href_cat(c)}"><span class="topic-icon">{ic(v['icon'],28)}</span><span class="topic-card-bottom"><strong>{E(v['name'])}</strong><span class="topic-count">{sum(1 for a in A if a['category']==c)} guides {ic('arrow-up-right',18)}</span></span><p>{E(v['description'])}</p></a>''' for c,v in CAT.items())
    featured=[next(x for x in A if x['slug']==s) for s in ['renew-nicop-from-abroad','open-roshan-digital-account','overseas-pakistani-property-tax-filer-rate','apostille-vs-attestation-pakistan','buying-property-in-pakistan-from-abroad','child-born-abroad-pakistani-documents']]
    shortcuts=[('Renew my NICOP','renew-nicop-from-abroad'),('Send money to Pakistan','send-money-to-pakistan-safely'),('Check a property','buying-property-in-pakistan-from-abroad'),('File an official complaint','complain-to-opf-from-abroad')]
    sc=''.join(f'<a href="guides/{slug}.html">{ic("check-circle",18)}<span>{E(title)}</span>{ic("arrow-up-right",17)}</a>' for title,slug in shortcuts)
    body=f'''<section class="home-hero"><div class="container hero-layout"><div class="hero-content"><div class="eyebrow"><span class="eyebrow-dot"></span> YOUR TRUSTED STARTING POINT</div><h1>Far from Pakistan.<br><em>Never far from answers.</em></h1><p class="hero-desc">Clear, practical guides for Pakistanis living abroad. Sort your documents, protect your money, understand property matters, and get things done—one step at a time.</p>
    <div class="hero-cta"><a href="guides/index.html" class="btn btn-primary btn-lg">Explore all guides {ic('arrow',19)}</a><button class="btn btn-white btn-lg search-launch">{ic('search',19)} Search a question</button></div><div class="hero-trust"><span>{ic('check-circle',18)} Researched with official sources</span><span>{ic('check-circle',18)} Always free to read</span></div></div>
    <div class="hero-art" aria-hidden="true"><div class="orb-halo"></div><div class="orbital orbital-1"></div><div class="orbital orbital-2"></div><div class="globe-art"><div class="globe-longitude"></div><div class="globe-latitude"></div><span class="orbit-dot dot-a"></span><span class="orbit-dot dot-b"></span><span class="orbit-dot dot-c"></span><span class="globe-initials">PS<span>.</span></span></div><div class="float-card card-one"><span class="float-icon">{ic('id-card',20)}</span><div><small>IDENTITY</small><strong>Documents, simplified</strong></div>{ic('check-circle',17)}</div><div class="float-card card-two"><span class="float-icon">{ic('wallet',20)}</span><div><small>MONEY</small><strong>Transfer with confidence</strong></div>{ic('check-circle',17)}</div><div class="float-card card-three"><span class="float-icon">{ic('house',20)}</span><div><small>PROPERTY</small><strong>Know before you buy</strong></div>{ic('check-circle',17)}</div><span class="hero-art-caption">A practical bridge back home</span></div></div></section>
    <section class="proof-band"><div class="container proof-inner"><span class="proof-label">Guidance checked against</span><div class="proof-logos"><span>NADRA</span><span>SBP</span><span>FBR</span><span>MOFA</span><span>HEC</span></div><span class="proof-note">Independent references, not endorsements</span></div></section>
    <section class="section container" id="topics"><div class="section-head"><div><div class="overline">FIND YOUR WAY</div><h2>What do you need help with?</h2><p>Choose a topic and get straight to the practical details.</p></div><a class="text-link" href="topics/index.html">All topics {ic('arrow',17)}</a></div><div class="topics-grid">{tiles}</div></section>
    <section class="section section--soft"><div class="container"><div class="section-head"><div><div class="overline">START HERE</div><h2>Popular questions, answered</h2><p>Step-by-step articles for the things that matter most.</p></div><a class="text-link" href="guides/index.html">View all {len(A)} guides {ic('arrow',17)}</a></div><div class="cards-grid">{''.join(card(a) for a in featured)}</div></div></section>
    <section class="section container"><div class="split-section"><div class="split-intro"><span class="overline">A LITTLE DIRECTION GOES A LONG WAY</span><h2>Not sure where<br>to begin?</h2><p>Tell us the problem. Start with one of the most-requested paths, then follow the official steps in each guide.</p><a href="tools/documents.html" class="btn btn-primary">Try the document finder {ic('arrow',18)}</a></div><div class="shortcut-list">{sc}</div></div></section>
    <section class="section section--soft"><div class="container"><div class="section-head"><div><div class="overline">MADE TO HELP</div><h2>Useful tools. No sign-up.</h2><p>A little preparation can prevent an expensive mistake.</p></div><a href="tools/index.html" class="text-link">Explore tools {ic('arrow',17)}</a></div><div class="tool-preview-grid"><a href="tools/documents.html" class="tool-preview"><span class="tool-preview-icon sky">{ic('compass',25)}</span><small>INTERACTIVE GUIDE</small><h3>Document finder</h3><p>Figure out which identity or family-document guide fits your situation.</p><span class="readlink">Open tool {ic('arrow',17)}</span></a><a href="tools/remittance-cost.html" class="tool-preview"><span class="tool-preview-icon mint">{ic('calculator',25)}</span><small>MANUAL CALCULATOR</small><h3>Remittance cost comparison</h3><p>Enter actual quotes and compare total rupees received, after fees.</p><span class="readlink">Open tool {ic('arrow',17)}</span></a><a href="tools/property-checklist.html" class="tool-preview"><span class="tool-preview-icon peach">{ic('shield',25)}</span><small>INTERACTIVE CHECKLIST</small><h3>Property safety checklist</h3><p>Track the documents and checks to complete before transferring money.</p><span class="readlink">Open tool {ic('arrow',17)}</span></a></div></div></section>
    <section class="section container"><div class="editorial-cta"><div class="editorial-art">{ic('shield',48)}</div><div><span class="overline">OUR EDITORIAL PROMISE</span><h2>Useful advice, with sources you can check.</h2><p>We prioritize official authorities, show when content was reviewed, and flag rules that may change. PakSights is independent and is not a government service.</p><a class="text-link" href="editorial-policy.html">How we research our guides {ic('arrow',18)}</a></div></div></section>'''
    return document('A Practical Guide for Overseas Pakistanis','Independent, official-source-referenced guides on NICOP, Pakistani passports, money transfers, property, tax, family documents and overseas complaints.',body,'index.html')

def listing():
    buttons=''.join(f'<button class="filter-button" data-filter="{c}" aria-pressed="false">{E(v["name"])}</button>' for c,v in CAT.items())
    rows=''.join(f'<div data-guide-card data-category="{a["category"]}" data-search="{E((a["title"]+" "+a["deck"]+" "+" ".join(a["tags"])).lower())}">{card(a,"../")}</div>' for a in A)
    body=f'''<section class="page-hero page-hero--compact"><div class="container">{breadcrumb([('Guides','guides/index.html')],'../')}<div class="overline">THE KNOWLEDGE LIBRARY</div><h1>Find a guide for your next step.</h1><p>From official forms to real-world checklists—browse {len(A)} researched guides, written for Pakistanis abroad.</p></div></section><section class="section container"><div class="listing-controls"><label class="input-search">{ic('search',21)}<input id="guide-search" type="search" placeholder="Search guides…" aria-label="Filter guides"></label><div class="filters"><button class="filter-button is-active" data-filter="all" aria-pressed="true">All topics</button>{buttons}</div><p class="result-count" id="result-count">Showing {len(A)} guides</p></div><div class="cards-grid" id="guide-grid">{rows}</div><p class="empty-state" id="guide-empty" hidden>No matching guides yet. Try a different word or topic.</p></section>'''
    return document('All overseas Pakistani guides','Browse evidence-based guides for overseas Pakistanis on identity, money, property, family and help services.',body,'guides/index.html','../','guides')

def topics_index():
    panels=''.join(f'''<a href="{c}.html" class="topic-index-card topic-card--{v['tone']}"><span class="topic-icon">{ic(v['icon'],30)}</span><div><h2>{E(v['name'])}</h2><p>{E(v['description'])}</p><span class="readlink">Explore {sum(1 for a in A if a['category']==c)} guides {ic('arrow',17)}</span></div></a>''' for c,v in CAT.items())
    body=f'''<section class="page-hero page-hero--compact"><div class="container">{breadcrumb([('Topics','topics/index.html')],'../')}<div class="overline">EXPLORE BY TOPIC</div><h1>Five parts of life. Clear steps for each.</h1><p>Start with the area that matters most to you today.</p></div></section><section class="section container"><div class="topics-index-grid">{panels}</div></section>'''
    return document('Topics for overseas Pakistanis','Browse five carefully focused categories of guides for overseas Pakistanis.',body,'topics/index.html','../','topics')

def topic_page(c):
    v=CAT[c]; aa=[a for a in A if a['category']==c]
    body=f'''<section class="page-hero page-hero--compact"><div class="container">{breadcrumb([('Topics','topics/index.html'),(v['name'],'topics/'+c+'.html')],'../')}<span class="topic-icon topic-icon--big topic-card--{v['tone']}">{ic(v['icon'],31)}</span><div class="overline">{len(aa)} DETAILED GUIDES</div><h1>{E(v['name'])}</h1><p>{E(v['description'])} Find actionable steps, preparation checklists and direct official links.</p></div></section><section class="section container"><div class="section-head"><div><span class="overline">PRACTICAL READING</span><h2>Guides in this topic</h2></div></div><div class="cards-grid">{''.join(card(a,'../') for a in aa)}</div><div class="bottom-nudge"><span>{ic('compass',27)}</span><div><strong>Need another topic?</strong><p>Browse all categories and tools to find a better fit.</p></div><a href="index.html" class="btn btn-outline">All topics {ic('arrow',17)}</a></div></section>'''
    return document(v['name']+' guides',v['description'],body,'topics/'+c+'.html','../','topics',ld_breadcrumb([('Home','index.html'),('Topics','topics/index.html'),(v['name'],'topics/'+c+'.html')]))

def article_page(a):
    c=a['category']; v=CAT[c]; url='guides/'+a['slug']+'.html'
    step_html=''.join(f'<div class="step"><div class="step-num">{i+1:02d}</div><div><h3>{E(s["title"])}</h3><p>{E(s["body"])}</p></div></div>' for i,s in enumerate(a['steps']))
    check_html=''.join(f'<label class="article-check"><input type="checkbox"><span>{E(x)}</span></label>' for x in a['checklist'])
    watch=''.join(f'<li>{E(x)}</li>' for x in a['watch'])
    faq=''.join(f'<details class="faq-item"><summary>{E(f["q"])}</summary><div><p>{E(f["a"])}</p></div></details>' for f in a['faqs'])
    sources=''.join(f'<li><span class="source-bullet">{ic("external",16)}</span><a href="{E(SRC[s]["url"])}" target="_blank" rel="noopener noreferrer">{E(SRC[s]["name"])}</a></li>' for s in a['sources'])
    related=[b for b in A if b['category']==c and b['slug']!=a['slug']][:3]
    if len(related)<3:related += [b for b in A if b['category']!=c][:3-len(related)]
    ld=[{'@context':'https://schema.org','@type':'Article','headline':a['title'],'description':a['deck'],'datePublished':a['published'],'dateModified':a['reviewed'],'author':{'@type':'Organization','name':'PakSights Editorial'},'publisher':{'@type':'Organization','name':'PakSights'},'mainEntityOfPage':BASE+url,'about':v['name'],'citation':[SRC[s]['url'] for s in a['sources']]},ld_breadcrumb([('Home','index.html'),('Guides','guides/index.html'),(a['title'],url)])]
    body=f'''<section class="article-top"><div class="container article-title-wrap">{breadcrumb([('Guides','guides/index.html'),(a['title'],url)],'../')}<div class="article-kicker"><span class="pill pill--{v['tone']}">{ic(v['icon'],15)} {E(v['name'])}</span><span class="date-meta">{ic('clock',16)} {rt(a)} min read</span></div><h1>{E(a['title'])}</h1><p class="article-deck">{E(a['deck'])}</p><div class="article-byline"><span class="byline-mark">PS</span><div><strong>PakSights Editorial</strong><span>Published {fmt_date(a["published"])} · Sources reviewed {fmt_date(a["reviewed"])}</span></div><div class="article-actions"><button class="icon-button article-print" title="Print guide" aria-label="Print guide">{ic('print',19)}</button><button class="icon-button article-copy" data-copy="{E(BASE+url)}" title="Copy link" aria-label="Copy link">{ic('link',19)}</button></div></div></div></section>
    <div class="container article-layout"><article class="article-body"><div class="answer-box"><div class="answer-heading">{ic('check-circle',20)} THE SHORT ANSWER</div><p>{E(a['answer'])}</p></div>
    <section id="understanding"><h2>What you should know first</h2>{''.join('<p>'+E(p)+'</p>' for p in a['context'])}</section>
    <section id="steps"><h2>Step-by-step: what to do</h2><p class="section-lead">Work through these actions in order. The official service may ask for additional information depending on your circumstances.</p><div class="steps-list">{step_html}</div></section>
    <section id="checklist"><h2>Before you begin: your checklist</h2><p class="section-lead">Tick the items as you prepare. These checkboxes are for your convenience; no details are sent to us.</p><div class="article-checklist">{check_html}</div><button class="small-action" onclick="window.print()">{ic('print',16)} Print this guide</button></section>
    <section id="mistakes"><h2>Common mistakes to avoid</h2><div class="caution-box"><div class="caution-title">{ic('alert',21)} Look out for these</div><ul>{watch}</ul></div></section>
    <section id="questions"><h2>Frequently asked questions</h2><div class="faq-list">{faq}</div></section>
    <section id="sources"><div class="source-section-header"><h2>Official sources & further reading</h2><span class="review-tag">{ic('shield',16)} Checked {fmt_date(a["reviewed"])}</span></div><p>These are the public authority pages referenced for this guide. Open them to confirm the latest rules, fees, availability and local requirements.</p><ul class="source-links">{sources}</ul><div class="disclaimer-strip">This is general information, not individual legal, immigration, tax or financial advice. Rules can change and individual circumstances matter. PakSights is not affiliated with the authorities linked here.</div></section>
    <section class="article-related"><h2>Keep reading</h2><div class="related-rows">{''.join(f'<a href="{href_guide(b,"../")}"><span>{E(b["title"])}</span>{ic("arrow-up-right",17)}</a>' for b in related)}</div></section></article>
    <aside class="article-aside"><div class="sticky-aside"><div class="aside-panel"><h3>On this page</h3><a href="#understanding">What to know first</a><a href="#steps">Step-by-step guide</a><a href="#checklist">Preparation checklist</a><a href="#mistakes">Mistakes to avoid</a><a href="#questions">FAQs</a><a href="#sources">Official sources</a></div><div class="aside-help"><span>{ic('shield',22)}</span><strong>Source-first guidance</strong><p>We link to the responsible authority so you can verify requirements before acting.</p><a href="../editorial-policy.html">Our editorial process {ic('arrow',16)}</a></div></div></aside></div>'''
    return document(a['title'],a['deck'],body,url,'../','guides',ld)
