def doc_finder():
    body=tool_header('Document finder','Which document guide do you need?','Choose your situation and we’ll point you to the right starting guide. We do not ask for your name or ID number.','documents')+'''<section class="section container tool-shell"><div class="tool-form"><div class="tool-form-head"><span class="tool-step-tag">01 / FIND YOUR PATH</span><h2>What are you trying to do?</h2><p>Choose the closest option. You can change it at any time.</p></div><fieldset class="choice-grid" id="doc-choices"><legend class="sr-only">Choose a document situation</legend><label><input type="radio" name="doc-goal" value="renew-nicop-from-abroad" checked><span>Renew my NICOP</span></label><label><input type="radio" name="doc-goal" value="nicop-vs-poc"><span>Choose NICOP or POC</span></label><label><input type="radio" name="doc-goal" value="renew-pakistani-passport-online"><span>Renew my passport</span></label><label><input type="radio" name="doc-goal" value="lost-identity-documents-abroad"><span>Replace a lost document</span></label><label><input type="radio" name="doc-goal" value="online-power-of-attorney-pakistan"><span>Authorize someone in Pakistan</span></label><label><input type="radio" name="doc-goal" value="child-born-abroad-pakistani-documents"><span>Register a child born abroad</span></label><label><input type="radio" name="doc-goal" value="nadra-frc-from-abroad"><span>Get a family certificate</span></label><label><input type="radio" name="doc-goal" value="apostille-vs-attestation-pakistan"><span>Attest documents</span></label></fieldset></div><div class="tool-result"><span class="result-head">{check}</span><div class="overline">YOUR STARTING POINT</div><h2 id="doc-result-title">How to renew your NICOP while living abroad</h2><p id="doc-result-deck">Start with NADRA's official PakID renewal instructions.</p><a href="../guides/renew-nicop-from-abroad.html" class="btn btn-primary" id="doc-result-link">Read your guide {arrow}</a><div class="tool-note">{shield} This finder is informational, not a government eligibility determination.</div></div></section>'''.replace('{check}',ic('check-circle',27)).replace('{arrow}',ic('arrow',18)).replace('{shield}',ic('shield',19))
    return document('Document guide finder','Find the right PakSights document guide for NICOP, POC, passports, family certificates and attestation.',body,'tools/documents.html','../','tools',extra_js='assets/js/tools.js')
def remit():
    body=tool_header('Remittance comparison','Which money transfer really costs less?','Enter two provider quotes to compare PKR paid out. Nothing is sent to a server, and rates are not live.','remittance-cost')+f'''<section class="section container"><div class="calculator-intro"><span>{ic('shield',23)}</span><p>Use <strong>the exact quotes shown at checkout</strong>. Enter the same amount to send for each provider, and specify whether fees come out of that amount or are charged on top. The calculator does not collect quotes or provide a provider recommendation.</p></div><div class="calc-grid"><div class="calc-card"><div class="calc-provider">PROVIDER A</div><label>Provider name <input id="a-name" value="Provider A" maxlength="40"></label><label>Sending amount (in your currency) <input id="a-amount" type="number" value="500" min="0" step="0.01"></label><label>Fee (in sending currency) <input id="a-fee" type="number" value="5" min="0" step="0.01"></label><label>PKR exchange rate per 1 unit <input id="a-rate" type="number" value="280" min="0" step="0.0001"></label><label>How is the fee charged?<select id="a-mode"><option value="extra">On top of sending amount</option><option value="deduct">Deducted from sending amount</option></select></label></div><div class="calc-card"><div class="calc-provider">PROVIDER B</div><label>Provider name <input id="b-name" value="Provider B" maxlength="40"></label><label>Sending amount (in your currency) <input id="b-amount" type="number" value="500" min="0" step="0.01"></label><label>Fee (in sending currency) <input id="b-fee" type="number" value="0" min="0" step="0.01"></label><label>PKR exchange rate per 1 unit <input id="b-rate" type="number" value="277" min="0" step="0.0001"></label><label>How is the fee charged?<select id="b-mode"><option value="extra">On top of sending amount</option><option value="deduct">Deducted from sending amount</option></select></label></div></div><div class="calc-results" aria-live="polite"><div class="overline">YOUR ESTIMATED COMPARISON</div><div id="remit-summary" class="remit-summary"></div><p class="calc-footnote">Estimates assume the quoted rate applies to the fee-adjusted transfer amount. No taxes, intermediary deductions, or other charges beyond the entered fee are included. If total charged differs, compare providers on the <strong>same total out-of-pocket cost</strong>.</p></div><div class="tool-postscript"><h2>Why a zero-fee offer can cost more</h2><p>A provider can charge no explicit transfer fee but offer a less favorable exchange rate. Compare both the total amount paid and the amount the recipient receives. Before confirming any real transfer, verify the final terms in the regulated provider's own checkout.</p><a class="text-link" href="../guides/send-money-to-pakistan-safely.html">Read our safer remittance guide {ic('arrow',17)}</a></div></section>'''
    return document('Money-transfer cost comparison','A free manual remittance calculator comparing two quotes using exchange rates and fees.',body,'tools/remittance-cost.html','../','tools',extra_js='assets/js/tools.js')
def property_check():
    groups=[('Identity & authority',['Identify the exact plot, parcel or land identifiers','Confirm the real seller or registered owner independently','Verify the developer, housing society or land authority','Check approvals, zoning and whether the property can be legally transferred']),('Title & records',['Obtain current official or certified ownership records','Review registration deeds and history of transfers with your own lawyer','Check encumbrances, disputed possession and pending litigation','Confirm all pending society dues and liabilities']),('Money & taxes',['Obtain a written schedule of taxes and transfer charges','Check FBR and applicable provincial tax conditions','Agree on traceable payments and documented milestones','Keep the complete payment and contract evidence']),('Representation & closing',['Appoint independent legal counsel not selected by the seller','Limit any POA to precisely defined actions','Confirm the receiving office accepts the POA/document form','Collect registered transfer evidence and verify your updated ownership record'])]
    form=''
    for gi,(name,items) in enumerate(groups):
        form+=f'<div class="property-group"><div class="property-group-head"><span>{str(gi+1).zfill(2)}</span><h3>{E(name)}</h3></div>'
        for ii,item in enumerate(items):form+=f'<label class="property-item"><input type="checkbox" data-property="{gi}-{ii}"><span>{E(item)}</span></label>'
        form+='</div>'
    body=tool_header('Property checklist','Before you buy property from abroad','A thoughtful, trackable list of checks to discuss with your own lawyer and the proper authorities.','property-checklist')+f'''<section class="section container"><div class="property-layout"><div><div class="property-toolbar"><div><span class="overline">YOUR PRIVATE CHECKLIST</span><h2>Due diligence before payment</h2><p>Progress is saved only in this browser. Tick a box only after you have verified it.</p></div><button class="btn btn-outline btn-sm" id="property-reset">Reset checklist</button></div><div class="property-form">{form}</div><div class="checklist-footer"><button class="btn btn-primary" onclick="window.print()">{ic('print',17)} Print checklist</button><a class="text-link" href="../guides/buying-property-in-pakistan-from-abroad.html">Read the full property guide {ic('arrow',17)}</a></div></div><aside class="property-progress"><div class="sticky-aside"><div class="progress-card"><span class="overline">PREPARATION PROGRESS</span><strong id="property-progress-number">0 / 16</strong><div class="progress-track"><div id="property-progress-bar"></div></div><p id="property-progress-message">Start with the official authority records.</p><div class="progress-warning">{ic('alert',19)} A completed list is not legal clearance. Always obtain independent professional review.</div></div><a href="../topics/property.html" class="text-link">More property guides {ic('arrow',17)}</a></div></aside></div></section>'''
    return document('Property due-diligence checklist','A free privacy-friendly checklist for overseas Pakistanis planning to purchase real estate in Pakistan.',body,'tools/property-checklist.html','../','tools',extra_js='assets/js/tools.js')
def info_page(kind):
    pages={
    'about':('About PakSights','A practical bridge to reliable information for Pakistanis overseas.',f'''<h2>Answers worth finding</h2><p>PakSights is an independent information website created to help overseas Pakistanis navigate real problems with a little more confidence. We focus on the paperwork, institutions, banking arrangements, property questions and family decisions that become complicated when you live in another country.</p><p>Our guides aim to answer a useful question: <em>“What should I do next, what should I prepare, and where can I check the official rule?”</em></p><h2>What makes this different?</h2><p>We publish practical steps instead of news headlines alone. We point to official authorities, distinguish stated rules from our practical suggestions and show a source-review date. We cannot decide cases or act for any government department.</p><p>PakSights is being rebuilt as an overseas-community information resource. Its articles are general guidance for readers in different countries, not personalized advice.</p><a class="btn btn-primary" href="guides/index.html">Explore practical guides {ic('arrow',17)}</a>'''),
    'editorial-policy':('Our editorial standards','How we choose sources, review claims and handle corrections.',f'''<h2>Primary sources come first</h2><p>For official procedures, we prioritize the responsible institution—such as NADRA for identity, DGI&P for passports, SBP for banking, FBR for tax, MOFA for consular matters, HEC for degrees and IBCC for school equivalence. We may use multiple official pages to check for context or conflicting guidance.</p><h2>What each guide contains</h2><p>Guides include a plain-English short answer, a sequence of actions, a preparation checklist, pitfalls, FAQs and a list of official source links. We try to avoid publishing precise fees, rates or guaranteed completion times unless we can confirm that they are current and relevant.</p><h2>Review and updates</h2><p>Initial site articles were prepared and source-checked on 10 November 2026. A “sources reviewed” date indicates when the linked guidance was consulted; it does <strong>not</strong> mean the responsible agency has approved our content or that rules cannot change. Changes after that date may not be reflected.</p><h2>Independent, not official</h2><p>PakSights is not affiliated with, sponsored by or endorsed by any government organization. We do not ask for NICOP numbers, login passwords, fees, bank details or private immigration documents through our tools.</p><h2>Reporting a correction</h2><p>If an authority page changes or a guide has an error, please use the contact instructions on our <a href="contact.html">contact page</a> once the editorial email is enabled. Include the article URL, claim, and official source link. We treat evidence-based corrections as a priority.</p>'''),
    'contact':('Contact & corrections','How to send a correction or suggestion for a PakSights guide.',f'''<h2>We welcome useful corrections</h2><p>Found a broken official link, a rule that changed, or an important overseas Pakistani question we have not covered? We want to hear about it.</p><div class="contact-card"><span>{ic('mail',27)}</span><div><h3>Editorial contact</h3><p id="contact-unavailable">Our editorial contact channel is being finalized. For time-sensitive matters, use the relevant authority’s own contact information. We will publish a working editorial email once it is available.</p><p id="contact-enabled" hidden><a id="contact-address" href="#">Send an editorial email</a></p></div></div><h2>What to include</h2><p>Share the guide title or URL, the sentence that needs updating and a link to the latest official authority page. Please do not email national ID numbers, passport scans, passwords, OTPs or financial information.</p><h2>Need urgent official help?</h2><p>PakSights is not a consulate, bank or emergency service. Use the appropriate government or local emergency channel. Our <a href="guides/find-pakistani-embassy-abroad.html">embassy directory guide</a> explains where to start.</p>'''),
    'privacy':('Privacy policy','How the static PakSights website and its local tools handle information.',f'''<h2>What this website collects</h2><p>This site is published as a static website. Our guide finder and remittance calculator run inside your browser and do not send your entries to a PakSights server. The property checklist stores ticks in your browser’s <code>localStorage</code> so the checklist can remember your progress on that device. You may clear it using the Reset button or by clearing site data.</p><h2>Hosting and technical logs</h2><p>When you visit a hosted page, the hosting provider may process standard technical data such as IP address, browser information and request logs to deliver the website and maintain security. Their practices are governed by their own policies.</p><h2>Advertising</h2><p>PakSights may display third-party ads, including Google AdSense, after the site owner configures advertising. If enabled, Google and its partners may use cookies or similar technology subject to their policies and applicable consent requirements. <strong>No advertising identifier is included in this launch package.</strong> The owner must update this policy and implement any required regional consent controls before activating ads.</p><h2>External links</h2><p>Official agency links open websites operated by third parties. Their collection practices and content are not controlled by PakSights.</p><h2>Your choices</h2><p>You can use the article pages without creating an account. You can reset local tool data and adjust browser privacy settings. Contact information must be configured by the site owner before launch.</p>'''),
    'disclaimer':('Disclaimer','Important limits of the information published on PakSights.',f'''<h2>General information only</h2><p>PakSights publishes general educational and practical information, not personalized legal, financial, immigration, property or tax advice. We are not a government agency, a law firm or a licensed financial intermediary.</p><h2>Rules change</h2><p>Government policies, fees, forms, service availability and laws may change without notice, and procedures can vary by province, embassy, destination country and personal circumstances. Check the linked authority’s active page immediately before applying, paying or signing anything.</p><h2>No official relationship</h2><p>Reference to NADRA, FBR, SBP, MOFA or any other organization does not mean that organization endorses PakSights. The links are provided to make independent verification easier.</p><h2>Professional decisions</h2><p>For property transfers, contested inheritance, citizenship issues or cross-border taxes, obtain individualized advice from a suitable qualified professional. Never disclose passwords, one-time codes or banking credentials to someone offering assistance through a third party.</p>'''),
    'terms':('Terms of use','Terms for accessing PakSights articles and interactive tools.',f'''<h2>Permitted use</h2><p>Content is supplied for personal information and educational purposes. You may read, link to and print guides for your own use. Do not present them as official government documents or misrepresent their authorship.</p><h2>Accuracy and availability</h2><p>We try to provide helpful information and official-source links, but cannot warrant completeness, error-free operation or uninterrupted availability. The linked authority is the source of truth for its current service and policies.</p><h2>Tools and calculations</h2><p>Our manual remittance calculator is a mathematical comparison of user-supplied inputs, not a live exchange-rate feed or financial advice. Check the provider’s final checkout. The property checklist is not title verification or legal due diligence.</p><h2>External websites</h2><p>We do not control third-party pages. Access to external services is governed by the relevant website’s terms and applicable law.</p>'''),
    }
    title,desc,content=pages[kind]
    body=f'''<section class="page-hero page-hero--compact"><div class="container">{breadcrumb([(title,kind+'.html')])}<div class="overline">PAKSIGHTS</div><h1>{E(title)}</h1><p>{E(desc)}</p></div></section><section class="section container info-layout"><article class="prose-page">{content}</article><aside class="info-aside"><div class="aside-help">{ic('shield',22)}<strong>Independent resource</strong><p>We are not a government agency. Browse our source directory to go directly to official departments.</p><a href="sources.html">Official sources {ic('arrow',16)}</a></div></aside></section>'''
    return document(title,desc,body,kind+'.html')
